def _dict(v:Any)->dict[str,Any]:return v if isinstance(v,dict) else {}
def _rows(n:Any)->list[dict[str,Any]]:
 v=_dict(n).get("rows");return [r for r in v if isinstance(r,dict)] if isinstance(v,list) else []
def _free_row(r):return {k:r.get(k) for k in _FREE_ROW_KEYS if k in r}
def _public_view(n,limit=20):
 d=_dict(n);rs=[_free_row(r) for r in _rows(d)[:limit]];return {"total":d.get("total",len(rs)),"rows":rs,"redacted_for_free":True}
